// Verifica campos obrigatórios
const required = ['temperature','vibration','current','production','timestamp'];
for (const field of required) {
    if (msg.payload[field] === undefined) {
        node.warn('Campo ausente: ' + field);
        return null;
    }
}
return msg;

const p = msg.payload;

// ── Regra de alerta ───────────────────────────────────
// SE temperature > 80 E vibration > 10 → ALERTA
// SENÃO → NORMAL
if (p.temperature > 80 && p.vibration > 10) {
    p.status = 'ALERTA';
} else {
    p.status = 'NORMAL';
}

// Garante timestamp ISO 8601
if (!p.timestamp) {
    p.timestamp = new Date().toISOString();
}

node.status({
    fill:  p.status === 'ALERTA' ? 'red' : 'green',
    shape: 'dot',
    text:  p.status + ' | T=' + p.temperature.toFixed(1)
             + '°C V=' + p.vibration.toFixed(2) + 'mm/s'
});

return msg;

const p = msg.payload;

// Payload de atualização NGSI-v2 (PATCH /v2/entities/{id}/attrs)
msg.payload = {
    temperature: { value: p.temperature, type: 'Number' },
    vibration:   { value: p.vibration,   type: 'Number' },
    current:     { value: p.current,     type: 'Number' },
    production:  { value: p.production,  type: 'Number' },
    status:      { value: p.status,      type: 'Text'   },
    timestamp:   { value: p.timestamp,   type: 'DateTime' }
};

msg.headers = { 'Content-Type': 'application/json' };
msg.method  = 'PATCH';
msg.url     = 'http://orion:1026/v2/entities/Crusher:001/attrs';

return msg;

const code = msg.statusCode;
if (code >= 200 && code < 300) {
    node.status({ fill:'green', shape:'dot', text:'OK ' + code });
} else {
    node.status({ fill:'red', shape:'ring', text:'ERRO ' + code });
    node.error('Orion retornou ' + code + ': ' + msg.payload);
}
return msg;
